  model=CatBoostRegressor(iterations=850,depth=depth,learning_rate=.035,l2_leaf_reg=5,verbose=False,random_seed=42,thread_count=2,allow_writing_files=False)
  models.append((f"cat_{depth}_{target}",model,"raw",target))
for depth in [2,3]: models.append((f"gbr_huber_{depth}",GradientBoostingRegressor(n_estimators=400,max_depth=depth,loss="huber",learning_rate=.03,min_samples_leaf=3,random_state=42),"raw","raw"))
